SELECT count(distinct u.testuser_user_id) FILTER (WHERE u.testuser_last_activity>=localtimestamp-interval '5 minutes') active_5m, count(*) FILTER (WHERE u.testuser_status IN (1,2,3) AND COALESCE(u.testuser_close_reason,'')='' AND u.testuser_creation_time+t.test_duration_time*interval '1 minute'>localtimestamp AND t.test_end_time>localtimestamp) in_progress, count(*) FILTER (WHERE (u.testuser_close_reason='completed' OR (u.testuser_status IN (3,4) AND COALESCE(u.testuser_close_reason,'') NOT IN ('timeout','blocked')))) completed_total, count(distinct u.testuser_user_id) FILTER (WHERE (u.testuser_close_reason='completed' OR (u.testuser_status IN (3,4) AND COALESCE(u.testuser_close_reason,'') NOT IN ('timeout','blocked')))) completed_users_total, count(*) FILTER (WHERE (u.testuser_close_reason='completed' OR (u.testuser_status IN (3,4) AND COALESCE(u.testuser_close_reason,'') NOT IN ('timeout','blocked'))) AND u.testuser_last_activity>=date_trunc('day',localtimestamp)) completed_today, count(*) FILTER (WHERE (u.testuser_close_reason='completed' OR (u.testuser_status IN (3,4) AND COALESCE(u.testuser_close_reason,'') NOT IN ('timeout','blocked'))) AND t.test_begin_time<=localtimestamp AND t.test_end_time>localtimestamp) completed_open, count(distinct u.testuser_user_id) FILTER (WHERE (u.testuser_close_reason='completed' OR (u.testuser_status IN (3,4) AND COALESCE(u.testuser_close_reason,'') NOT IN ('timeout','blocked'))) AND t.test_begin_time<=localtimestamp AND t.test_end_time>localtimestamp) completed_users_open FROM tce_tests_users u JOIN tce_tests t ON t.test_id=u.testuser_test_id WHERE NOT COALESCE(u.testuser_pregenerated,false) AND u.testuser_status BETWEEN 1 AND 4